\label{lemma-locally-constant-on-connected}
Let $X$ be a connected scheme. Let $\overline{x}$ be a geometric point of $X$.
\begin{enumerate}
\item There is an equivalence of categories
$$
\left\{
\begin{matrix}
\text{finite locally constant}\\
\text{sheaves of sets on }X_\etale
\end{matrix}
\right\}
\longleftrightarrow
\left\{
\begin{matrix}
\text{finite }\pi_1(X, \overline{x})\text{-sets}
\end{matrix}
\right\}
$$
\item There is an equivalence of categories
$$
\left\{
\begin{matrix}
\text{finite locally constant}\\
\text{sheaves of abelian groups on }X_\etale
\end{matrix}
\right\}
\longleftrightarrow
\left\{
\begin{matrix}
\text{finite }\pi_1(X, \overline{x})\text{-modules}
\end{matrix}
\right\}
$$
\item Let $\Lambda$ be a finite ring. There is an equivalence of categories
$$
\left\{
\begin{matrix}
\text{finite type, locally constant}\\
\text{sheaves of }\Lambda\text{-modules on }X_\etale
\end{matrix}
\right\}
\longleftrightarrow
\left\{
\begin{matrix}
\text{finite }\pi_1(X, \overline{x})\text{-modules endowed}\\
\text{with commuting }\Lambda\text{-module structure}
\end{matrix}
\right\}
$$
\end{enumerate}
\end{lemma}

\begin{proof}
We observe that $\pi_1(X, \overline{x})$ is a profinite
topological group, see Fundamental Groups, Definition
\ref{pione-definition-fundamental-group}.
The left hand categories are defined in
Section \ref{section-locally-constant}.
The notation used in the right hand categories is taken from
Fundamental Groups, Definition \ref{pione-definition-G-set-continuous}
for sets and
Definition \ref{definition-G-module-continuous} for abelian groups.
This explains the notation.

\medskip\noindent
Assertion (1) follows from
Lemma \ref{lemma-characterize-finite-locally-constant}
and Fundamental Groups, Theorem \ref{pione-theorem-fundamental-group}.
Parts (2) and (3) follow immediately from this by endowing the underlying
(sheaves of) sets with additional structure. For example, a finite
locally constant sheaf of abelian groups on $X_\etale$ is the same thing
as a finite locally constant sheaf of sets $\mathcal{F}$
together with a map $+ : \mathcal{F} \times \mathcal{F} \to \mathcal{F}$
satisfying the usual axioms. The equivalence in (1) sends products
to products and hence sends $+$ to an addition on the corresponding
finite $\pi_1(X, \overline{x})$-set. Since $\pi_1(X, \overline{x})$-modules
are the same thing as $\pi_1(X, \overline{x})$-sets with a compatible
abelian group structure we obtain (2). Part (3) is proved in
exactly the same way.
\end{proof}

\begin{lemma}

target_context:
\label{lemma-locally-constant-on-connected}
Soit $X$ un sch\'ema connexe. Soit $\overline{x}$ un point g\'eom\'etrique de $X$.
\begin{enumerate}
\item Il existe une \`equivalence de cat\'egories
$$
\left\{
\begin{matrix}
\text{faisceaux d'ensembles localement constants finis}\\
\text{sur }X_\etale
\end{matrix}
\right\}
\longleftrightarrow
\left\{
\begin{matrix}
\text{ensembles finis munis d'une action de }\pi_1(X, \overline{x})
\end{matrix}
\right\}
$$
\item Il existe une \`equivalence de cat\'egories
$$
\left\{
\begin{matrix}
\text{faisceaux de groupes ab\'eliens localement constants finis}\\
\text{sur }X_\etale
\end{matrix}
\right\}
\longleftrightarrow
\left\{
\begin{matrix}
\pi_1(X, \overline{x})\text{-modules finis}
\end{matrix}
\right\}
$$
\item Soit $\Lambda$ un anneau fini. Il existe une \`equivalence de cat\'egories
$$
\left\{
\begin{matrix}
\text{faisceaux localement constants de type fini}\\
\text{de }\Lambda\text{-modules sur }X_\etale
\end{matrix}
\right\}
\longleftrightarrow
\left\{
\begin{matrix}
\pi_1(X, \overline{x})\text{-modules finis munis}\\
\text{d'une structure commutante de }\Lambda\text{-module}
\end{matrix}
\right\}
$$
\end{enumerate}
\end{lemma}

\begin{proof}
Remarquons que $\pi_1(X, \overline{x})$ est un groupe topologique
profini, voir Fundamental Groups, définition
\ref{pione-definition-fundamental-group}.
Les cat\'egories des membres de gauche sont d\'efinies dans la
section \ref{section-locally-constant}.
La notation employ\'ee dans les membres de droite vient de
Fundamental Groups, définition \ref{pione-definition-G-set-continuous}
pour les ensembles et de la
d\'efinition \ref{definition-G-module-continuous} pour les groupes ab\'eliens.
Cela explique la notation.

\medskip\noindent
L'assertion (1) r\'esulte du
lemme \ref{lemma-characterize-finite-locally-constant}
et de Fundamental Groups, théorème \ref{pione-theorem-fundamental-group}.
Les parties (2) et (3) s'en d\'eduisent imm\'ediatement en munissant les
(faisceaux d')ensembles sous-jacents d'une structure suppl\'ementaire. Par exemple, un
faisceau de groupes ab\'eliens localement constant fini sur $X_\etale$ revient
\`a un faisceau d'ensembles localement constant fini $\mathcal{F}$
muni d'un morphisme $+ : \mathcal{F} \times \mathcal{F} \to \mathcal{F}$
satisfaisant aux axiomes usuels. L'\'equivalence de (1) pr\'eserve les produits
et transforme donc $+$ en une addition sur l'ensemble fini correspondant
muni d'une action de $\pi_1(X, \overline{x})$. Puisque les $\pi_1(X, \overline{x})$-modules
reviennent aux ensembles munis d'une action de $\pi_1(X, \overline{x})$ et d'une
structure compatible de groupe ab\'elien, nous obtenons (2). La partie (3) se d\'emontre
exactement de la m\^eme mani\`ere.
\end{proof}

\begin{lemma}

